const activityApi = {
  list: (companyId, filters) => {
    const params = new URLSearchParams();
    if (filters?.scope) params.set("scope", filters.scope);
    else if (filters?.entityType) params.set("entityType", filters.entityType);
    if (filters?.entityId) params.set("entityId", filters.entityId);
    if (filters?.agentId) params.set("agentId", filters.agentId);
    const qs = params.toString();
    return api.get(`/companies/${companyId}/activity${qs ? `?${qs}` : ""}`);
  },
  forIssue: (issueId) => api.get(`/issues/${issueId}/activity`),
  runsForIssue: (issueId) => api.get(`/issues/${issueId}/runs`),
  issuesForRun: (runId) => api.get(`/heartbeat-runs/${runId}/issues`)
};

