  upsertEntity: (entity) => api.post(`${BASE$2}/entities`, entity),
  // DELETE /entities/:id
  deleteEntity: (id) => api.delete(`${BASE$2}/entities/${id}`),
  // GET /graph — Visualization data
  getGraph: (params) => {
    const qs = new URLSearchParams();
    if (params?.limit) qs.set("limit", String(params.limit));
    if (params?.types) qs.set("types", params.types);
    const q = qs.toString();
    return api.get(`${BASE$2}/graph${q ? `?${q}` : ""}`);
  },
  // POST /traverse — Depth traversal
  traverse: (params) => api.post(`${BASE$2}/traverse`, params),
  // POST /ingest — LLM extraction results
  ingest: (data) => api.post(`${BASE$2}/ingest`, data),
  // POST /seed — Trigger seeding
  seed: () => api.post(`${BASE$2}/seed`, {}),
  // GET /stats
  getStats: () => api.get(`${BASE$2}/stats`),
  // GET /dedup
  getDedup: (status = "pending") => api.get(`${BASE$2}/dedup?status=${status}`),
