function getForceParams(nodeCount) {
  if (nodeCount < 30) {
    return { charge: -30, linkDistance: 20, centerStrength: 0.5, collideRadius: 8 };
  }
  if (nodeCount <= 60) {
    return { charge: -40, linkDistance: 28, centerStrength: 0.4, collideRadius: 10 };
  }
  return { charge: -50, linkDistance: 35, centerStrength: 0.3, collideRadius: 12 };
}
function getDepthOpacity(depth) {
  switch (depth) {
    case 0:
      return 1;
    // selected
    case 1:
      return 1;
    // 1-hop
    case 2:
      return 0.8;
    // 2-hop
    case 3:
      return 0.6;
    // 3-hop
    default:
      return 0.4;
  }
}
function getEntityMass(type) {
  switch (type) {
    case "organization":
      return 8;
    case "project":
      return 6;
    case "person":
      return 4;
    case "task":
      return 3;
    default:
      return 2;
  }
}

