  restartFacebookWeb: (name) => api.post(`/channels/facebook-web/${encodeURIComponent(name)}/restart`, {}),
  verifyFacebookWeb: (name) => api.get(`/channels/facebook-web/${encodeURIComponent(name)}/verify`),
