const trainingApi = {
  start: (payload) => api.post("/training/start", payload),
  cancel: (sessionId) => api.post("/training/cancel", { session_id: sessionId }),
  listSessions: async (limit = 50) => {
    const res = await api.get(
      `/training/sessions?limit=${limit}`
    );
    return res.sessions || [];
  },
  getTurns: async (sessionId) => {
    const res = await api.get(
      `/training/sessions/${sessionId}/turns`
    );
    return res.turns || [];
  },
  getScores: async (sessionId) => {
    const res = await api.get(
      `/training/sessions/${sessionId}/scores`
    );
    return res.scores || [];
  },
  listAuditLog: async (params = {}) => {
    const qs = new URLSearchParams();
    if (params.agent) qs.set("agent", params.agent);
    if (params.tool) qs.set("tool", params.tool);
    if (params.success) qs.set("success", params.success);
    if (params.limit) qs.set("limit", String(params.limit));
    const suffix = qs.toString() ? `?${qs.toString()}` : "";
    const res = await api.get(`/training/audit-log${suffix}`);
    return res.entries || [];
  }
};
function openTrainingLiveSocket(sessionId) {
  try {
    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
    const url = `${protocol}//${window.location.host}/api/training/live/${sessionId}`;
    return new WebSocket(url);
  } catch (err) {
    return null;
  }
}

